#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { parseGraph, findCycle, analyse, pack, CliError } from './graph.js'

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  if (!((mode === 'waves' || mode === 'explain') && args.length === 1) && !(mode === 'pack' && args.length === 2)) {
    throw new CliError(usage, 2)
  }
  let workers = 0
  if (mode === 'pack') {
    if (!/^[1-9][0-9]*$/.test(args[1])) throw new CliError('error: workers must be a positive integer', 2)
    workers = Number(args[1])
  }
  const graph = parseGraph(readFileSync(0, 'utf8'))
  const cycle = findCycle(graph)
  if (cycle) throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
  const info = analyse(graph)
  const names = [...graph.costs.keys()].sort(cmp)
  let out = ''
  if (mode === 'waves') {
    const waves = []
    for (const n of names) (waves[info.depth.get(n)] ??= []).push(n)
    waves.forEach((w, k) => { out += `wave ${k}: ${w.join(' ')}\n` })
    out += `total ${info.total}\n`
  } else if (mode === 'explain') {
    for (const n of names) out += `${n} start=${info.start.get(n)} finish=${info.finish.get(n)} depth=${info.depth.get(n)}\n`
    out += `total ${info.total}\n`
  } else {
    out = pack(graph, info, workers)
  }
  process.stdout.write(out)
}

function cmp(a, b) { return a < b ? -1 : a > b ? 1 : 0 }

try {
  main()
} catch (e) {
  if (!(e instanceof CliError)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
EOF
cat > src/graph.js <<'EOF'
export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const costs = new Map()
  const deps = new Map()
  const used = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const N = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new CliError(`error: line ${N}: expected task <name> <cost>`, 2)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new CliError(`error: line ${N}: invalid task name ${w[1]}`, 2)
      if (!/^[0-9]+$/.test(w[2])) throw new CliError(`error: line ${N}: cost must be a non-negative integer`, 2)
      if (costs.has(w[1])) throw new CliError(`error: line ${N}: task ${w[1]} is declared twice`, 2)
      costs.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new CliError(`error: line ${N}: expected dep <name> <dependency>...`, 2)
      for (const n of w.slice(1)) used.push(n)
      if (!deps.has(w[1])) deps.set(w[1], new Set())
      for (const d of w.slice(2)) deps.get(w[1]).add(d)
    } else {
      throw new CliError(`error: line ${N}: unknown directive ${w[0]}`, 2)
    }
  })
  for (const n of used) if (!costs.has(n)) throw new CliError(`error: unknown task ${n}`, 2)
  const dmap = new Map()
  for (const n of costs.keys()) dmap.set(n, [...(deps.get(n) ?? [])].sort(cmp))
  return { costs, deps: dmap }
}

export function findCycle(g) {
  const state = new Map()
  const stack = []
  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    for (const d of g.deps.get(n)) {
      if (state.get(d) === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!state.has(d)) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(n, 2)
    return null
  }
  for (const n of [...g.costs.keys()].sort(cmp)) {
    if (!state.has(n)) {
      const c = visit(n)
      if (c) return c
    }
  }
  return null
}

export function analyse(g) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  const prio = new Map()
  const rev = new Map([...g.costs.keys()].map((n) => [n, []]))
  for (const [n, ds] of g.deps) for (const d of ds) rev.get(d).push(n)
  const calc = (n) => {
    if (finish.has(n)) return
    let s = 0n
    let dp = 0
    for (const d of g.deps.get(n)) {
      calc(d)
      if (finish.get(d) > s) s = finish.get(d)
      dp = Math.max(dp, depth.get(d) + 1)
    }
    start.set(n, s)
    finish.set(n, s + g.costs.get(n))
    depth.set(n, dp)
  }
  const pr = (n) => {
    if (prio.has(n)) return prio.get(n)
    let m = 0n
    for (const x of rev.get(n)) { const v = pr(x); if (v > m) m = v }
    prio.set(n, m + g.costs.get(n))
    return prio.get(n)
  }
  let total = 0n
  for (const n of g.costs.keys()) {
    calc(n)
    pr(n)
    if (finish.get(n) > total) total = finish.get(n)
  }
  return { start, finish, depth, prio, total }
}

export function pack(g, info, workers) {
  const free = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const fin = new Map()
  const pending = new Set(g.costs.keys())
  let t = 0n
  let makespan = 0n
  while (pending.size) {
    for (;;) {
      let w = free.findIndex((f) => f <= t)
      if (w < 0) break
      let best = null
      for (const n of pending) {
        if (!g.deps.get(n).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null) { best = n; continue }
        const a = info.prio.get(n), b = info.prio.get(best)
        if (a > b || (a === b && n < best)) best = n
      }
      if (best === null) break
      const f = t + g.costs.get(best)
      pending.delete(best)
      fin.set(best, f)
      free[w] = f
      ran[w].push(`${best}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    let next = null
    for (const f of free) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  let out = ''
  ran.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
  return out + `makespan ${makespan}\n`
}
