export function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    r.authority = e < 0 ? s.slice(2) : s.slice(2, 2 + e)
    s = e < 0 ? '' : s.slice(2 + e)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function splitAuthority(a) {
  let userinfo, hostport = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); hostport = a.slice(at + 1) }
  const rb = hostport.lastIndexOf(']')
  const c = hostport.indexOf(':', rb + 1)
  let host = hostport, port
  if (c >= 0) { host = hostport.slice(0, c); port = hostport.slice(c + 1) }
  return { userinfo, host, port }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const bad = /%(?![0-9A-Fa-f]{2})/

export function checkPercent(r) {
  const parts = { path: r.path, userinfo: undefined, host: undefined, query: r.query, fragment: r.fragment }
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    parts.userinfo = a.userinfo
    parts.host = a.host
  }
  for (const k of ['path', 'userinfo', 'host', 'query', 'fragment']) {
    if (parts[k] !== undefined && bad.test(parts[k])) return k
  }
  return null
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const pct = (s) => s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
  const c = String.fromCharCode(parseInt(h, 16))
  return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
})
const defaults = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let auth
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    auth = ''
    if (a.userinfo !== undefined) auth += pct(a.userinfo) + '@'
    auth += lower(pct(a.host))
