const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

const join = (p, k) => (p === '' ? k : `${p}.${k}`)

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.c)) this.i++
  }
  atEnd() {
    return this.i >= this.s.length || this.c === '#' || this.c === ';'
  }

  quoted(q) {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const ch = this.c
      if (ch === q) {
        this.i++
