    const c = this.c
    if (c === '"' || c === "'") return this.quoted(c)
    const st = this.i
    while (isBare(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else {
        this.i = save
        return parts
      }
    }
