export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // per round: Map name -> votes
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const pick = b.ranking.find((c) => continuing.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const counts = [...votes].map(([name, v]) => ({ name, votes: v }))
    counts.sort((x, y) => cmp(y.votes, x.votes) || cmp(x.name, y.name))
    const round = { number: history.length, counts, exhausted: total - active }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: undefined }
    const top = counts[0]
    if (top.votes * 2n > active) return { rounds, winner: top.name }
    let tied = counts.filter((c) => c.votes === counts[counts.length - 1].votes).map((c) => c.name)
    while (tied.length > 1) {
      let reduced = false
      for (const h of history) {
        const vs = tied.map((t) => h.get(t))
        const min = vs.reduce((m, v) => (v < m ? v : m))
        if (vs.some((v) => v !== min)) {
          tied = tied.filter((t) => h.get(t) === min)
          reduced = true
          break
        }
      }
