const COUNT = /^[1-9][0-9]*$/

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const tok = line.split(/\s+/)
    const word = tok[0]
    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw err(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      if (tok.length < 2) throw err(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of tok.slice(1)) {
        if (!NAME.test(name)) throw err(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw err(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = tok.slice(1)
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw err(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      if (tok.length < 3) throw err(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!COUNT.test(tok[1])) throw err(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of tok.slice(2)) {
        if (!candidates.includes(name)) throw err(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw err(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(tok[1]), ranking: tok.slice(2) })
    } else {
      throw err(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (candidates === null) throw err('error: no candidates')
  return { candidates, ballots }
}
