{"file_path":"src/addr.js","content":"export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 27 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 65)
}

// Returns {col,row,name} for an in-range address (any case), else null.
export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { col: colIndex(letters), row, name: letters + row }
}
"}

{"file_path":"src/parse.js","content":"function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if (s.startsWith('<=', i) || s.startsWith('>=', i) || s.startsWith('<>', i)) {
      toks.push({ k: 'op', v: s.slice(i, i + 2) }); i += 2; continue
    }
    if ('^*/+-=<>(),:'.includes(ch)) { toks.push({ k: 'op', v: ch }); i++; continue }
    return null
  }
  return toks
}

class Fail extends Error {}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return { ok: false }
  let pos = 0
  let misplaced = false
  const peek = (v) => pos < toks.length && toks[pos].k === 'op' && toks[pos].v === v
  const expect = (v) => { if (!peek(v)) throw new Fail(); pos++ }

  function cmp() {
    let l = add()
    while (pos < toks.length && toks[pos].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[pos].v)) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peek('+') || peek('-')) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (peek('*') || peek('/')) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peek('^')) { pos++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peek('-') || peek('+')) {
      const op = toks[pos++].v
      return { type: 'unary', op, x: unary() }
    }
    return primary()
  }
  function primary() {
    if (pos >= toks.length) throw new Fail()
    const t = toks[pos]
    if (t.k === 'num') { pos++; return { type: 'num', v: Number(t.v) } }
    if (t.k === 'op' && t.v === '(') {
      pos++
      const x = cmp()
      expect(')')
      return { type: 'paren', x }
    }
    if (t.k === 'word') {
      pos++
      if (peek('(')) {
        pos++
        const args = []
        if (!peek(')')) {
          for (;;) {
            args.push(arg())
            if (peek(',')) { pos++; continue }
            break
          }
        }
        expect(')')
        return { type: 'call', name: t.v.toUpperCase(), args }
      }
      if (peek(':')) {
        pos++
        if (pos >= toks.length || toks[pos].k !== 'word') throw new Fail()
        misplaced = true
        return { type: 'range', a: t.v, b: toks[pos++].v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { type: 'bool', v: true }
      if (u === 'FALSE') return { type: 'bool', v: false }
      return { type: 'ref', name: t.v }
    }
    throw new Fail()
  }
  function arg() {
    if (
      pos + 2 < toks.length &&
      toks[pos].k === 'word' && toks[pos + 1].k === 'op' && toks[pos + 1].v === ':' &&
      toks[pos + 2].k === 'word' &&
      pos + 3 < toks.length && toks[pos + 3].k === 'op' && (toks[pos + 3].v === ',' || toks[pos + 3].v === ')')
    ) {
      const n = { type: 'range', a: toks[pos].v, b: toks[pos + 2].v }
      pos += 3
      return n
    }
    return cmp()
  }

  try {
    const node = cmp()
    if (pos !== toks.length) return { ok: false }
    return { ok: true, node, misplaced }
  } catch (e) {
    if (e instanceof Fail) return { ok: false }
    throw e
  }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { parseAddr } from './addr.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const isErr = (x) => x.t === 'e'

export function format(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    case 's': return v.v
    default: return v.v
  }
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}
function finite(x) {
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}
function cmpStr(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cmpStr(a.v, b.v)
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.stack = new Set()
    this.parsed = new Map()
  }

  valueOf(addr) {
    if (this.memo.has(addr)) return this.memo.get(addr)
    const cell = this.cells.get(addr)
    if (!cell) return num(0)
    if (this.stack.has(addr)) return err('#CYCLE!')
    this.stack.add(addr)
    let v
    try {
      v = this.compute(cell.content)
    } finally {
      this.stack.delete(addr)
    }
    this.memo.set(addr, v)
    return v
  }

  compute(content) {
    if (content.startsWith('=')) {
      const r = parseFormula(content.slice(1))
      if (!r.ok || r.misplaced) return err('#ERR!')
      return this.ev(r.node)
    }
    if (content === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.includes(content)) return err(content)
    return { t: 's', v: content }
  }

  ref(name) {
    const p = parseAddr(name)
    if (!p) return err('#REF!')
    return this.valueOf(p.name)
  }

  ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': return this.ref(n.name)
      case 'paren': return this.ev(n.x)
      case 'range': return err('#ERR!')
      case 'unary': {
        const x = this.ev(n.x)
        if (isErr(x)) return x
        const v = toNum(x)
        if (isErr(v)) return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
