{"command":"cat package.json; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/
const policies = new Map()
const routes = new Map()
const events = []
let started = false
let lastTick = null

function num(field, s, least) {
  if (!INT.test(s) || BigInt(s) < least) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      directive(f)
    } catch (e) {
      if (e instanceof Fail) {
        process.stderr.write(`error: line ${i + 1}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }
}

function directive(f) {
  const d = f[0]
  const late = () => { if (started) throw new Fail('declarations must come before the first event') }
  if (d === 'bucket') {
    if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
    late()
    if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
    const capacity = num('capacity', f[2], 1n)
    const refill = num('refill', f[3], 0n)
    const per = num('per', f[4], 1n)
    if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
    policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per, states: new Map() })
  } else if (d === 'window') {
    if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
    late()
    if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
    const limit = num('limit', f[2], 0n)
    const span = num('span', f[3], 1n)
    if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
    policies.set(f[1], { name: f[1], kind: 'window', limit, span, states: new Map() })
  } else if (d === 'route') {
    if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
    late()
    if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
    if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
    const list = []
    for (const p of f.slice(2)) {
      if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
      list.push(policies.get(p))
    }
    routes.set(f[1], list)
  } else if (d === 'event') {
    if (f.length !== 3) throw new Fail('expected event <tick> <key>')
    const tick = num('tick', f[1], 0n)
    if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
    if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
    started = true
    lastTick = tick
    events.push([tick, f[2]])
  } else {
    throw new Fail(`unknown directive ${d}`)
  }
}

function advance(p, key, tick) {
  let s = p.states.get(key)
  if (p.kind === 'bucket') {
    if (!s) {
      s = { tokens: p.capacity * p.per, last: tick }
      p.states.set(key, s)
    } else {
      const max = p.capacity * p.per
      s.tokens += p.refill * (tick - s.last)
      if (s.tokens > max) s.tokens = max
      s.last = tick
    }
  } else {
    if (!s) { s = { ticks: [] }; p.states.set(key, s) }
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
  return s
}

parse(readFileSync(0, 'utf8'))

function routeFor(key) {
  let best = null
  for (const [prefix, list] of routes) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, list }
  }
  return best && best.list
}

const out = []
const stats = new Map()
let ta = 0
let td = 0
for (const [tick, key] of events) {
  const list = routeFor(key)
  let refused = null
  if (list) {
    const sts = list.map((p) => advance(p, key, tick))
    for (let i = 0; i < list.length; i++) {
      const p = list[i]
      const ok = p.kind === 'bucket' ? sts[i].tokens >= p.per : BigInt(sts[i].ticks.length) < p.limit
      if (!ok) { refused = p.name; break }
    }
    if (refused === null) {
      list.forEach((p, i) => {
        if (p.kind === 'bucket') sts[i].tokens -= p.per
        else sts[i].ticks.push(tick)
      })
    }
  }
  const st = stats.get(key) || { a: 0, d: 0 }
  stats.set(key, st)
  if (refused === null) { st.a++; ta++ } else { st.d++; td++ }
  out.push(refused === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${refused}`)
}
if (mode === 'summary') {
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  const lines = keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  lines.push(`total allowed=${ta} denied=${td}`)
  process.stdout.write(lines.join('\n') + '\n')
} else if (out.length) {
  process.stdout.write(out.join('\n') + '\n')
}
EOF
