    } else if (n === undefined) {
      const t = newTable(); t.hdr = true
      cur.m.set(last, t); st.cur = t
    } else if (n.t !== 'table') fail(full + ' is not a table')
    else {
      if (n.hdr) fail('table ' + full + ' is defined twice')
