import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function num(field, s, least) {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function run(text) {
  const policies = new Map()
  const routes = new Map()
  const states = new Map() // policy name -> Map(key -> state)
  const events = []
  let started = false
  let prev = null
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const w = t[0]
    try {
      if (w === 'bucket' || w === 'window' || w === 'route') {
        if (started) throw new Fail('declarations must come before the first event')
      }
      if (w === 'bucket') {
        if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        const capacity = num('capacity', t[2], 1)
        const refill = num('refill', t[3], 0)
        const per = num('per', t[4], 1)
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'bucket', capacity, refill, per })
      } else if (w === 'window') {
        if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        const limit = num('limit', t[2], 0)
        const span = num('span', t[3], 1)
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], { kind: 'window', limit, span })
      } else if (w === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        for (const p of t.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
        routes.set(t[1], t.slice(2))
      } else if (w === 'event') {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num('tick', t[1], 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${tick} is before tick ${prev}`)
        prev = tick
        started = true
        events.push([tick, t[2]])
      } else {
        throw new Fail(`unknown directive ${w}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })

  const out = []
  const counts = new Map()
  for (const [tick, key] of events) {
    let best = null
    for (const p of routes.keys()) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    let allowed = true
    let denier = null
    if (best !== null) {
      const names = routes.get(best)
      const sts = names.map((n) => {
        const pol = policies.get(n)
        let m = states.get(n)
        if (!m) states.set(n, (m = new Map()))
        let s = m.get(key)
        if (!s) {
          s = pol.kind === 'bucket' ? { units: pol.capacity * pol.per, last: tick } : { ticks: [] }
          m.set(key, s)
        }
        if (pol.kind === 'bucket') {
          const cap = pol.capacity * pol.per
          s.units += pol.refill * (tick - s.last)
          if (s.units > cap) s.units = cap
          s.last = tick
        } else {
          const cut = tick - pol.span
          s.ticks = s.ticks.filter((x) => x > cut)
        }
        return s
      })
      for (let j = 0; j < names.length; j++) {
        const pol = policies.get(names[j])
        const ok = pol.kind === 'bucket' ? sts[j].units >= pol.per : BigInt(sts[j].ticks.length) < pol.limit
        if (!ok) { allowed = false; denier = names[j]; break }
      }
      if (allowed) {
        names.forEach((n, j) => {
          const pol = policies.get(n)
          if (pol.kind === 'bucket') sts[j].units -= pol.per
          else sts[j].ticks.push(tick)
        })
      }
    }
    out.push(`${tick} ${key} ${allowed ? 'allow' : 'deny ' + denier}`)
    const c = counts.get(key) || [0, 0]
    c[allowed ? 0 : 1]++
    counts.set(key, c)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let a = 0, d = 0, s = ''
  for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    const [x, y] = counts.get(k)
    a += x; d += y
    s += `${k} allowed=${x} denied=${y}\n`
  }
  return s + `total allowed=${a} denied=${d}\n`
}

let result
try {
  result = run(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(result)
EOF
