import { readFileSync } from 'node:fs'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'rounds' && mode[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  const E = (m) => fail(`error: line ${n}: ${m}`)
  if (w[0] === 'candidates') {
    if (cands !== null || ballots.length) E('candidates must be declared once, before any ballot')
    if (w.length < 2) E('expected candidates <name>...')
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!NAME.test(name)) E(`invalid candidate name ${name}`)
      if (seen.has(name)) E(`candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = [...seen]
  } else if (w[0] === 'ballot') {
    if (cands === null) E('candidates must be declared once, before any ballot')
    if (w.length < 3) E('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(w[1])) E('count must be a positive integer')
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (!cands.includes(name)) E(`unknown candidate ${name}`)
      if (seen.has(name)) E(`candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: Number(w[1]), prefs: w.slice(2) })
  } else {
    E(`unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const total = ballots.reduce((s, b) => s + b.count, 0)
const continuing = new Set(cands)
const history = []
const out = []
let winner = null
for (;;) {
  const counts = new Map([...continuing].map((c) => [c, 0]))
  let active = 0
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
  }
  history.push(counts)
  const listed = [...counts.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  let line = `round ${history.length}: ` + listed.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0) break
  const top = listed.find(([, v]) => v * 2 > active)
  if (top) { winner = top[0]; break }
  let s = [...continuing]
  const min = Math.min(...s.map((c) => counts.get(c)))
  s = s.filter((c) => counts.get(c) === min)
  let r = 0
  while (s.length > 1 && r < history.length) {
    const vals = s.map((c) => history[r].get(c))
    const m = Math.min(...vals)
    if (vals.some((v) => v !== m)) { s = s.filter((c) => history[r].get(c) === m); r = 0 } else r++
  }
  const el = s.reduce((a, b) => (a > b ? a : b))
  continuing.delete(el)
  out.push(`eliminated ${el}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
process.stdout.write((mode[0] === 'rounds' ? out.join('\n') + '\n' : `rounds ${history.length}\n`) + end + '\n')
EOF
