import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  // consume a digit run with single underscores between digits; returns true if any digit
  const run = (pred) => {
    if (!pred(s[i])) return false
    while (i < n) {
      if (pred(s[i])) adv()
      else if (s[i] === '_' && pred(s[i - 1]) && pred(s[i + 1])) adv()
      else break
    }
    return true
  }

  while (i < n) {
    const c = s[i]
    const sl = line
    const sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      adv()
      adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') {
          adv()
          adv()
          depth++
        } else if (s[i] === '*' && s[i + 1] === '/') {
          adv()
          adv()
          depth--
        } else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      adv()
      adv()
      let v = ''
      while (i < n && s[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isIdStart(c)) {
      let v = ''
      while (i < n && isIdPart(s[i])) v += adv()
      tokens.push([sl, sc, KEYWORDS.has(v) ? 'keyword' : 'ident', v])
      continue
    }
    if (isDigit(c)) {
      const start = i
      let bad = false
      const p = s[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        adv()
        adv()
        const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        if (!run(pred)) bad = true
      } else {
        run(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) {
          adv()
          run(isDigit)
        }
        if (s[i] === 'e' || s[i] === 'E') {
          if (isDigit(s[i + 1]) || ((s[i + 1] === '+' || s[i + 1] === '-') && isDigit(s[i + 2]))) {
            adv()
            if (!isDigit(s[i])) adv()
            run(isDigit)
          }
        }
      }
      if (bad || isIdPart(s[i])) {
        while (i < n && isIdPart(s[i])) adv()
        throw new ScanError(sl, sc, `invalid number ${s.slice(start, i).join('')}`)
      }
      tokens.push([sl, sc, 'number', s.slice(start, i).join('')])
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = s[i]
        if (d === '"') {
          adv()
          break
        }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') {
          v += adv()
          continue
        }
        const bl = line
        const bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!isHex(s[i]) || !isHex(s[i + 1])) throw bad()
          v += String.fromCharCode(parseInt(s[i] + s[i + 1], 16))
