      adv()
      tokens.push([sl, sc, 'punct', two])
      continue
    }
    if (PUNCT1.has(c)) {
      adv()
      tokens.push([sl, sc, 'punct', c])
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
try {
  const tokens = scan(readFileSync(0, 'utf8'))
  let out = ''
  if (args[0] === 'tokens') {
    for (const [l, c, k, b] of tokens) out += `${l}:${c} ${k} ${b}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t[2] === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
