const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^\p{L}$/u.test(c)
const isWordChar = (c) => isLetter(c) || isDigit(c) || c === '_'

class Stop extends Error {}

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const fail = (l, c, reason) => {
    throw Object.assign(new Stop(), { l, c, reason })
  }
