  const run = (isD) => {
    if (!isD(cs[i])) return false
    adv()
    for (;;) {
      if (isD(cs[i])) adv()
      else if (cs[i] === '_' && isD(cs[i + 1])) {
        adv()
        adv()
      } else break
    }
    return true
