    while (i < n) {
      const c = cs[i]
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        adv()
        continue
      }
      const l = line
      const k = col
      if (c === '/' && cs[i + 1] === '/') {
        while (i < n && cs[i] !== '\n') adv()
        continue
      }
      if (c === '/' && cs[i + 1] === '*') {
        adv()
        adv()
        let depth = 1
        while (depth > 0) {
          if (i >= n) fail(l, k, 'unterminated block comment')
          if (cs[i] === '/' && cs[i + 1] === '*') {
            adv()
            adv()
            depth++
          } else if (cs[i] === '*' && cs[i + 1] === '/') {
            adv()
            adv()
            depth--
          } else adv()
        }
        continue
      }
      if (c === 'r' && cs[i + 1] === '"') {
        adv()
        adv()
        let s = ''
        for (;;) {
