        const s = cs.slice(start, i).join('')
        if (!ok) fail(l, k, `invalid number ${s}`)
        push(l, k, 'number', s)
        continue
      }
      if (c === '"') {
        adv()
        let s = ''
        for (;;) {
          if (i >= n) fail(l, k, 'unterminated string')
          const el = line
          const ec = col
          const d = adv()
          if (d === '"') break
          if (d === '\n') fail(el, ec, 'newline in string')
          if (d !== '\\') {
            s += d
            continue
          }
          if (i >= n) fail(l, k, 'unterminated string')
          const e = adv()
          const bad = () => fail(el, ec, `invalid escape \\${e}`)
          if (e === 'n') s += '\n'
          else if (e === 't') s += '\t'
          else if (e === 'r') s += '\r'
          else if (e === '\\') s += '\\'
          else if (e === '"') s += '"'
          else if (e === '0') s += '\0'
          else if (e === 'x') {
            if (!isHex(cs[i]) || !isHex(cs[i + 1])) bad()
            s += String.fromCharCode(parseInt(adv() + adv(), 16))
          } else if (e === 'u') {
            if (cs[i] !== '{') bad()
            let j = i + 1
            let h = ''
            while (isHex(cs[j])) h += cs[j++]
            if (h === '' || cs[j] !== '}') bad()
            const v = parseInt(h, 16)
            if (v > 0x10ffff) bad()
            while (i <= j) adv()
            s += String.fromCodePoint(v)
          } else bad()
        }
        push(l, k, 'string', JSON.stringify(s))
        continue
      }
      const two = c + (cs[i + 1] || '')
      if (PUNCT2.includes(two)) {
        adv()
        adv()
        push(l, k, 'punct', two)
        continue
      }
      if (PUNCT1.includes(c)) {
        adv()
        push(l, k, 'punct', c)
        continue
      }
      fail(l, k, `unexpected character ${c}`)
    }
  } catch (e) {
    if (e instanceof Stop) return { error: { line: e.l, col: e.c, reason: e.reason } }
