const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ t: 'e', v: code })
const num = (v) => ({ t: 'n', v })

class Syntax extends Error {}

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: m[0] }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length
    } else if (s.startsWith('<>', i) || s.startsWith('<=', i) || s.startsWith('>=', i)) {
      toks.push({ k: 'op', v: s.slice(i, i + 2) }); i += 2
    } else if ('^*/+-=<>(),:'.includes(c)) {
      toks.push({ k: 'op', v: c }); i++
    } else throw new Syntax()
  }
  return toks
}

// Parses a formula body. Returns {ast, misplaced}; throws Syntax.
function parse(body) {
  const toks = tokenize(body)
  let p = 0
  let misplaced = false
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].k === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) throw new Syntax(); p++ }

  function range() {
    const a = toks[p].v
    p += 2
    if (!toks[p] || toks[p].k !== 'word') throw new Syntax()
    const b = toks[p++].v
    return { type: 'range', a, b }
  }
  const atRange = () =>
    toks[p] && toks[p].k === 'word' && toks[p + 1] && toks[p + 1].k === 'op' && toks[p + 1].v === ':'

  function cmp() {
    let l = add()
    while (toks[p] && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { type: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { type: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) throw new Syntax()
    if (t.k === 'num') { p++; return { type: 'num', v: Number(t.v) } }
    if (t.k === 'op') {
      if (t.v === '(') {
        p++
        const e = cmp()
        expect(')')
        return e
      }
      throw new Syntax()
    }
    if (atRange()) { misplaced = true; return range() }
    const up = t.v.toUpperCase()
    const next = toks[p + 1]
    if (next && next.k === 'op' && next.v === '(') {
      p += 2
      const args = []
      if (!isOp(')')) {
        for (;;) {
          args.push(atRange() ? range() : cmp())
          if (isOp(',')) { p++; continue }
          break
        }
      }
      expect(')')
      return { type: 'call', name: up, args }
    }
    p++
    if (up === 'TRUE') return { type: 'bool', v: true }
    if (up === 'FALSE') return { type: 'bool', v: false }
    return { type: 'ref', word: t.v }
  }

  const ast = cmp()
  if (p !== toks.length) throw new Syntax()
  return { ast, misplaced }
}

function compileCell(cell) {
  if (cell.compiled) return cell.compiled
  const c = cell.content
  let r
  if (c[0] === '=') {
    try {
      const { ast, misplaced } = parse(c.slice(1))
      r = { formula: true, ast, misplaced }
    } catch (e) {
      if (!(e instanceof Syntax)) throw e
      r = { formula: true, bad: true }
    }
  } else {
    let value
    if (c === '') value = num(0)
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) value = num(Number(c))
    else if (ERRORS.includes(c)) value = err(c)
    else value = { t: 's', v: c }
    r = { formula: false, value }
  }
  cell.compiled = r
  return r
}

function rangeCells(node) {
  const a = parseAddr(node.a)
  const b = parseAddr(node.b)
  if (!a || !b) return null
  const out = []
  const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(c * 1000 + r)
  return out
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}

function finite(x) {
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') {
    const x = Array.from(a.v), y = Array.from(b.v)
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

function makeEvaluator(cells) {
  const memo = new Map()
  const busy = new Set()

  function cellValue(key) {
    if (memo.has(key)) return memo.get(key)
    const cell = cells.get(key)
    if (!cell) return num(0)
    if (busy.has(key)) return err('#CYCLE!')
    busy.add(key)
    const c = compileCell(cell)
    let v
    if (!c.formula) v = c.value
    else if (c.bad || c.misplaced) v = err('#ERR!')
    else v = ev(c.ast)
    busy.delete(key)
    memo.set(key, v)
    return v
  }

  function ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': {
        const a = parseAddr(n.word)
        return a ? cellValue(a.key) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'neg': {
        const v = ev(n.e)
        if (v.t === 'e') return v
        const x = toNum(v)
        if (x.t === 'e') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return binary(n)
      case 'call': return call(n)
    }
  }

  function binary(n) {
    const l = ev(n.l)
    const r = ev(n.r)
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const d = compare(l, r)
      const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      case '^': return finite(Math.pow(a.v, b.v))
    }
  }

  function call(n) {
    const name = n.name
    const argc = n.args.length
    const multi = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (!multi.includes(name) && name !== 'ABS' && name !== 'IF') return err('#NAME?')
    if (multi.includes(name) ? argc < 1 : name === 'ABS' ? argc !== 1 : argc !== 3) return err('#ERR!')
    if (name === 'IF' || name === 'ABS') {
      if (n.args.some((a) => a.type === 'range')) return err('#ERR!')
    }
    if (name === 'IF') {
      const c = ev(n.args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return ev(truth ? n.args[1] : n.args[2])
    }
    if (name === 'ABS') {
      const v = ev(n.args[0])
      if (v.t === 'e') return v
      const x = toNum(v)
      return x.t === 'e' ? x : num(Math.abs(x.v))
    }
    const vals = []
    for (const a of n.args) {
      if (a.type === 'range') {
        const keys = rangeCells(a)
        if (!keys) { vals.push(err('#REF!')); continue }
        for (const k of keys) vals.push(cellValue(k))
      } else vals.push(ev(a))
    }
    const firstErr = vals.find((v) => v.t === 'e')
    if (firstErr) return firstErr
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'e') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(nums.reduce((s, x) => Math.min(s, x)))
      case 'MAX': return num(nums.reduce((s, x) => Math.max(s, x)))
      case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }

  return cellValue
}

function format(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'e': return v.v
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function sorted(cells) {
  return [...cells.values()].sort((a, b) => a.addr.key - b.addr.key)
}

export function evaluateAll(cells) {
  const value = makeEvaluator(cells)
  let out = ''
  for (const cell of sorted(cells)) out += `${cell.addr.name}=${format(value(cell.addr.key))}\n`
  return out
}

function collect(n, set) {
  if (!n) return
  switch (n.type) {
    case 'ref': { const a = parseAddr(n.word); if (a) set.set(a.key, a.name); break }
    case 'range': {
      const keys = rangeCells(n)
      if (keys) for (const k of keys) set.set(k, null)
      break
    }
    case 'neg': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': for (const a of n.args) collect(a, set); break
  }
}

const colName = (col) => (col > 26 ? String.fromCharCode(64 + Math.floor((col - 1) / 26)) : '') + String.fromCharCode(65 + ((col - 1) % 26))

export function depsOf(cells) {
  let out = ''
  for (const cell of sorted(cells)) {
    const c = compileCell(cell)
    let line = `${cell.addr.name}:`
    if (c.formula && !c.bad) {
      const set = new Map()
      collect(c.ast, set)
      const keys = [...set.keys()].sort((a, b) => a - b)
      for (const k of keys) line += ` ${colName(Math.floor(k / 1000))}${k % 1000}`
    }
    out += line + '\n'
  }
  return out
}
"}

