import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) { super(msg); this.code = code }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const cost = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (cost.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      cost.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      depLines.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  const deps = new Map([...cost.keys()].map((k) => [k, new Set()]))
  for (const names of depLines) for (const x of names) if (!cost.has(x)) throw new Fail(`error: unknown task ${x}`)
  for (const [t, ...ds] of depLines) for (const d of ds) deps.get(t).add(d)
  return { cost, deps }
}

function checkCycle(names, deps) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const d of [...deps.get(u)].sort(cmp)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d))
        cyc.push(d)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const n of names) if (!state.get(n)) visit(n)
}

function main() {
  const a = process.argv.slice(2)
  const usage = new Fail('error: usage: cli.js waves|explain|pack <workers>')
  let workers = 0
  if (a.length === 1 && (a[0] === 'waves' || a[0] === 'explain')) {
    /* ok */
  } else if (a.length === 2 && a[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(a[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(a[1])
  } else throw usage

  const { cost, deps } = parse(readFileSync(0, 'utf8'))
  const names = [...cost.keys()].sort(cmp)
  checkCycle(names, deps)

  const start = new Map(), finish = new Map(), depth = new Map()
  const calc = (u) => {
    if (finish.has(u)) return
    let s = 0n, d = 0
    for (const x of deps.get(u)) {
      calc(x)
      if (finish.get(x) > s) s = finish.get(x)
      if (depth.get(x) + 1 > d) d = depth.get(x) + 1
    }
    start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
  }
  names.forEach(calc)
  let total = 0n
  for (const f of finish.values()) if (f > total) total = f

  let out = ''
  if (a[0] === 'waves') {
    const waves = []
    for (const n of names) (waves[depth.get(n)] ??= []).push(n)
    waves.forEach((w, k) => { out += `wave ${k}: ${w.join(' ')}\n` })
    out += `total ${total}\n`
  } else if (a[0] === 'explain') {
    for (const n of names) out += `${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}\n`
    out += `total ${total}\n`
  } else {
    const prio = new Map()
    const rev = new Map(names.map((n) => [n, []]))
    for (const n of names) for (const d of deps.get(n)) rev.get(d).push(n)
    const pr = (u) => {
      if (prio.has(u)) return prio.get(u)
      let m = 0n
      for (const x of rev.get(u)) { const p = pr(x); if (p > m) m = p }
      prio.set(u, m + cost.get(u))
      return m + cost.get(u)
    }
    names.forEach(pr)
    const order = [...names].sort((x, y) => (prio.get(x) === prio.get(y) ? cmp(x, y) : prio.get(x) > prio.get(y) ? -1 : 1))
    const done = new Map()
    const started = new Set()
    const freeAt = Array(workers).fill(0n)
    const ran = Array.from({ length: workers }, () => [])
    let t = 0n
    let remaining = names.length
    while (remaining > 0) {
      for (;;) {
        const w = freeAt.findIndex((f) => f <= t)
        if (w < 0) break
        const task = order.find((n) => !started.has(n) && [...deps.get(n)].every((d) => done.has(d) && done.get(d) <= t))
        if (task === undefined) break
        started.add(task)
        remaining--
        const f = t + cost.get(task)
        done.set(task, f)
        freeAt[w] = f
        ran[w].push(`${task}@${t}-${f}`)
      }
      if (remaining === 0) break
      let next = null
      for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
      if (next === null) break
      t = next
    }
    ran.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
    out += `makespan ${total}\n`
  }
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
