  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('usage: cli.js merge|merge2|regions')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) {
  if (l === '%%%') docs.push([])
  else docs[docs.length - 1].push(l)
}
if (docs.length !== 3) fail('expected three parts separated by %%%')
const [mine, base, theirs] = docs

function changes(side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j, who })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(); i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const all = [...changes(mine, 0), ...changes(theirs, 1)]
all.sort((a, b) => a.bs - b.bs || a.who - b.who)

const regs = [] // {kind, lines} or conflict
let pos = 0
let k = 0
const stable = (upTo) => {
  if (upTo > pos) regs.push({ kind: 'stable', lines: base.slice(pos, upTo) })
}
while (k < all.length) {
  const rs = all[k].bs
  let re = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= re) {
    re = Math.max(re, all[k].be)
    group.push(all[k++])
  }
  stable(rs)
  pos = re
  if (group.length === 1) {
    const c = group[0]
    regs.push({ kind: c.who ? 'theirs' : 'mine', lines: (c.who ? theirs : mine).slice(c.ss, c.se) })
    continue
  }
  const baseL = base.slice(rs, re)
  const side = (who, arr) => {
    const g = group.filter(c => c.who === who)
    if (!g.length) return baseL
    const minBs = Math.min(...g.map(c => c.bs)), maxBe = Math.max(...g.map(c => c.be))
    const minSs = Math.min(...g.map(c => c.ss)), maxSe = Math.max(...g.map(c => c.se))
    return arr.slice(minSs - (minBs - rs), maxSe + (re - maxBe))
  }
  const m = side(0, mine), t = side(1, theirs)
  const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])
  if (eq(m, t)) regs.push({ kind: 'both', lines: m })
  else if (eq(m, baseL)) regs.push({ kind: 'theirs', lines: t })
  else if (eq(t, baseL)) regs.push({ kind: 'mine', lines: m })
  else regs.push({ kind: 'conflict', m, b: baseL, t })
}
stable(base.length)

const out = []
let conflict = false
for (const r of regs) {
  if (r.kind === 'conflict') {
    conflict = true
    if (mode === 'regions') out.push(`conflict mine=${r.m.length} base=${r.b.length} theirs=${r.t.length}`)
    else {
      out.push('<<<<<<< mine', ...r.m)
      if (mode === 'merge') out.push('||||||| base', ...r.b)
      out.push('=======', ...r.t, '>>>>>>> theirs')
    }
  } else if (mode === 'regions') out.push(`${r.kind} ${r.lines.length}`)
  else out.push(...r.lines)
}
process.stdout.write(out.map(l => l + '\n').join(''))
process.exitCode = conflict ? 1 : 0
EOF
